import { Suspense } from 'react'

export function CardStats({
  dataPromise,
  totalRevenue,
  totalInvoices,
}: {
  dataPromise?: Promise<{ totalRevenue: number; totalInvoices: number }>
  totalRevenue?: number
  totalInvoices?: number
}) {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        {dataPromise ? (
          <Suspense fallback={<p>Loading...</p>}>
            <RevenueValue dataPromise={dataPromise} />
          </Suspense>
        ) : (
          <p>{totalRevenue !== undefined ? `$${totalRevenue.toLocaleString()}` : 'Loading...'}</p>
        )}
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        {dataPromise ? (
          <Suspense fallback={<p>Loading...</p>}>
            <InvoicesValue dataPromise={dataPromise} />
          </Suspense>
        ) : (
          <p>{totalInvoices !== undefined ? totalInvoices : 'Loading...'}</p>
        )}
      </div>
    </div>
  )
}

async function RevenueValue({
  dataPromise,
}: {
  dataPromise: Promise<{ totalRevenue: number }>
}) {
  const data = await dataPromise
  return <p>${data.totalRevenue.toLocaleString()}</p>
}

async function InvoicesValue({
  dataPromise,
}: {
  dataPromise: Promise<{ totalInvoices: number }>
}) {
  const data = await dataPromise
  return <p>{data.totalInvoices}</p>
}

